-- Official SG questions published by IPA for FY2025 (15 questions).
-- Source: https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf
-- Answer IDs are mapped from IPA's official answer key. Japanese content is from the public IPA paper; explanations are editorial study notes.
INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2025-01','exam-sg','リスクマネジメント','standard','single_choice','【2025年度 IPA公開問題 問1】JIS Q 31000:2019 のリスクマネジメントプロセスに関する記述のうち、適切なものはどれか。','[{"id":"a","text":"リスク対応の意義は、プロセスの設計、実施及び結末の質及び効果を保証し、改善することである。"},{"id":"b","text":"リスク特定の意義は、リスクに対処するための選択肢を選定し、実施することである。"},{"id":"c","text":"リスク評価の意義は、組織の目的の達成を助ける又は妨害する可能性のあるリスクを発見し、認識し、記述することである。"},{"id":"d","text":"リスク分析の意義は、必要に応じてリスクのレベルを含め、リスクの性質及び特徴を理解することである。"}]','"d"','リスク分析はリスクの性質・特徴やレベルを理解するプロセス。リスクを発見・記述するのはリスク特定、対応策を選び実施するのはリスク対応。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-02','exam-sg','SIEM','standard','single_choice','【2025年度 IPA公開問題 問2】SIEM 製品によるセキュリティ上の効果として、最も適切なものはどれか。','[{"id":"a","text":"様々な機器のログを集中管理し、横断的な分析や相関分析によって、目視では発見困難な兆候を検知・分析・可視化する。"},{"id":"b","text":"通信経路上のパケットをキャプチャし、暗号化データが改ざんされていないか確認する。"},{"id":"c","text":"ファイアウォール、IDS、マルウェア対策など複数の機能を一つの機器で実現する。"},{"id":"d","text":"ファイル改ざんを検知すると、事前のバックアップから直ちに自動修復する。"}]','"a"','SIEM は複数機器のログを集約し、相関分析で不審な兆候を検出・可視化する仕組み。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-03','exam-sg','ゼロトラスト','standard','single_choice','【2025年度 IPA公開問題 問3】ゼロトラストの説明として、最も適切なものはどれか。','[{"id":"a","text":"修正プログラムなどが提供されていない脆弱性が残っている状態"},{"id":"b","text":"内部ネットワークであっても必ずしも安全ではないことを前提として対策を講じる考え方"},{"id":"c","text":"秘密情報そのものを明かさず、秘密情報を知っていることを相手に知らせる方法"},{"id":"d","text":"マルウェア定義ファイルを用いず、PC の振る舞いから感染を検知する手法"}]','"b"','ゼロトラストはネットワークの内外だけで信頼を決めず、アクセスごとに認証・認可や状況確認を行う考え方。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-04','exam-sg','内部不正','standard','single_choice','【2025年度 IPA公開問題 問4】不正のトライアングルの構成要素の説明として、適切なものはどれか。','[{"id":"a","text":"機会とは、技術・物理環境・組織ルールなど、内部者の不正を可能又は容易にする環境である。"},{"id":"b","text":"情報と伝達とは、ノルマによるプレッシャなどのことである。"},{"id":"c","text":"正当化とは、内部者が不正行為を自ら納得させるための理由付けである。"},{"id":"d","text":"動機とは、情報を組織内外に正しく伝える仕組みである。"}]','"a"','不正のトライアングルは動機・機会・正当化。選択肢 a は「機会」の説明であり、他の選択肢は要素を取り違えている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-05','exam-sg','DNS','standard','single_choice','【2025年度 IPA公開問題 問5】DNS キャッシュサーバでの DNS キャッシュポイズニング攻撃の対策はどれか。','[{"id":"a","text":"DNS サービスの待受けポートを 53 番に固定する。"},{"id":"b","text":"外部の DNS クライアントからの再帰的問合せを受け付けない設定にする。"},{"id":"c","text":"権威 DNS サーバへの問合せに使用するトランザクション ID を固定する。"},{"id":"d","text":"権威 DNS サーバへの非再帰的問合せを行う設定にする。"}]','"b"','外部からの不要な再帰問い合わせを制限すると、キャッシュサーバが攻撃者に悪用されるリスクを下げられる。トランザクション ID を固定するのは危険。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-06','exam-sg','CVSS','standard','single_choice','【2025年度 IPA公開問題 問6】CVSS v3 の現状評価基準の特徴はどれか。','[{"id":"a","text":"攻撃コードの出現や利用可能な対策のレベルなどに応じ、評価結果が時間の経過で変化する。"},{"id":"b","text":"脆弱性と想定される脅威に応じ、製品利用者ごとに評価結果が異なる。"},{"id":"c","text":"利用者が対応を決めるための基準であり、評価結果は時間の経過で変化しない。"},{"id":"d","text":"利用環境によらず同じ評価結果となり、時間の経過でも変化しない。"}]','"a"','現状評価基準（Temporal）は攻撃コードの有無や対策状況など時間とともに変化する要素を評価する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-07','exam-sg','法令','standard','single_choice','【2025年度 IPA公開問題 問7】特定電子メール法の説明として、適切なものはどれか。','[{"id":"a","text":"広告メールの送信を受託した事業者だけを規制する。"},{"id":"b","text":"受信拒否の通知があった場合にだけ広告宣伝メールを禁止する方式である。"},{"id":"c","text":"取引の公平と通信傍受を目的として広告メールを規制する。"},{"id":"d","text":"規制対象となる電子メールの送信者及び送信委託者に対する義務を規定している。"}]','"d"','特定電子メール法は、規制対象となる広告宣伝メールの送信者や送信委託者などに義務を定めている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-08','exam-sg','システム監査','standard','single_choice','【2025年度 IPA公開問題 問8】情報セキュリティ違反を犯した従業員への懲戒手続を定めた社内規程を監査した。監査報告書に指摘事項として記載すべきものはどれか。','[{"id":"a","text":"違反の可能性を認識したら、直ちに懲戒手続を開始すると定めている。"},{"id":"b","text":"業務への影響度や教育状況を考慮した段階別の対応を定めている。"},{"id":"c","text":"恣意性を排除した公平な取扱いを定めている。"},{"id":"d","text":"懲戒手続の細則を策定し、従業員に周知徹底すると定めている。"}]','"a"','違反の可能性だけで直ちに懲戒を開始するのは適切でない。事実確認や状況の評価を経ずに処分する運用は、公平性・適正手続の観点から問題となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-09','exam-sg','サービス管理','standard','single_choice','【2025年度 IPA公開問題 問9】満足度の目標は5点満点中4.0点。回答数は、5点が50人、4点が250人、3点が150人、2点が50人、1点が0人だった。目標達成率＝満足度平均点÷目標値 とすると、目標達成率はいくらか。','[{"id":"a","text":"0.6"},{"id":"b","text":"0.72"},{"id":"c","text":"0.8"},{"id":"d","text":"0.9"}]','"d"','平均点は (5×50＋4×250＋3×150＋2×50)÷500＝3.6 点。目標達成率は 3.6÷4.0＝0.9。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-10','exam-sg','信頼性','standard','single_choice','【2025年度 IPA公開問題 問10】システムの信頼性指標 RASIS のうち、安全性を除く四つについて、適切な記述はどれか。','[{"id":"a","text":"R（信頼性）は MTBF（平均故障間隔）によって表す。"},{"id":"b","text":"A（可用性）は、稼働している時間の平均値によって表す。"},{"id":"c","text":"S（保守性）は、システムの稼働率によって表す。"},{"id":"d","text":"I（完全性）は、システムの故障率によって表す。"}]','"a"','信頼性は MTBF などで評価される。稼働率は可用性、故障率は信頼性関連の指標であり、保守性や完全性とは異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-11','exam-sg','データ分析','standard','single_choice','【2025年度 IPA公開問題 問11】企業全体のデータを統合・整理したデータウェアハウスから、特定の分析目的のためにデータを加工して構築したものはどれか。','[{"id":"a","text":"データカタログ"},{"id":"b","text":"データマート"},{"id":"c","text":"データリネージ"},{"id":"d","text":"データレイク"}]','"b"','データマートは、特定の部門や分析目的に合わせてデータウェアハウスなどから切り出して構築するデータ集合。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-12','exam-sg','DX','standard','single_choice','【2025年度 IPA公開問題 問12】製造業のデジタル化のうち、組織横断の業務変革や顧客起点の価値創出を伴うデジタルトランスフォーメーションに該当するものはどれか。','[{"id":"a","text":"高性能カメラで製造物を撮影し、出荷検査の証拠データとして保存する。"},{"id":"b","text":"熟練工の動きをセンサーで記録し、AIで動作モデルを作成する。"},{"id":"c","text":"顧客の販売・在庫情報と部品メーカーの生産・在庫情報を組み合わせ、AIで需給調整案を分析しサプライチェーン全体を最適化する。"},{"id":"d","text":"AI画像解析で自社の出荷時検品作業を効率化する。"}]','"c"','DX は個別工程のデジタル化にとどまらず、組織横断で業務やビジネスモデルを変革する。サプライチェーン全体の最適化が該当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-13','exam-sg','クラウド・リスク評価','standard','single_choice','【2025年度 IPA公開問題 問13】ある IT サービス企業がクラウドサービスの可用性評価を行う。顧客からの問合せ受付・回答に使う電子メールと、マイナンバーを含む人事・労務管理サービスについて、社内基準に従って重要度（0＝停止しても直ちに自社・顧客に影響なし、1＝自社に直ちに影響、2＝顧客にも直ちに影響）を評価する。電子メール、人事・労務管理の組合せはどれか。','[{"id":"a","text":"0、0"},{"id":"b","text":"0、1"},{"id":"c","text":"0、2"},{"id":"d","text":"1、0"},{"id":"e","text":"1、1"},{"id":"f","text":"1、2"},{"id":"g","text":"2、0"},{"id":"h","text":"2、1"},{"id":"i","text":"2、2"}]','"h"','顧客対応に直接使う電子メールの停止は顧客にも影響するため重要度2。人事・労務管理は社内業務に直ちに影響するが、基準上は重要度1。組合せは2、1。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-14','exam-sg','クラウド・インシデント対応','standard','single_choice','【2025年度 IPA公開問題 問14】取引先とのファイル受渡しに、アクセス権をいつでも付与・取消しでき、ダウンロードのログを確認できるクラウドストレージを利用する。誤ったメールアドレスを指定したと気付いた場合の対応と、ログでダウンロードされていないことを確認できた場合の判断を含む空欄の組合せはどれか。','[{"id":"a","text":"アクセス権の取消し／アップロード／情報漏えい"},{"id":"b","text":"アクセス権の取消し／アップロード／受信者がURLに未アクセス"},{"id":"c","text":"アクセス権の取消し／ダウンロード／情報漏えい"},{"id":"d","text":"アクセス権の取消し／ダウンロード／受信者がURLに未アクセス"},{"id":"e","text":"メールで通知／アップロード／情報漏えい"},{"id":"f","text":"メールで通知／アップロード／受信者がURLに未アクセス"},{"id":"g","text":"メールで通知／ダウンロード／情報漏えい"},{"id":"h","text":"メールで通知／ダウンロード／受信者がURLに未アクセス"}]','"c"','誤送信に気付いたらアクセス権を取り消す。ダウンロード記録がないことから判断できるのは、情報漏えいが発生していない可能性であり、単にメール通知を取り消すことではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-2025-15','exam-sg','個人情報保護','standard','single_choice','【2025年度 IPA公開問題 問15】ヘルスケアアプリの顧客属性データと健康データから匿名加工情報を作成し、マーケティング分析に利用する。電子メールアドレス、分析に必要な勤務先業種、体重に適用する匿名加工手法の組合せとして適切なものはどれか。手法は項目削除、一般化、トップ（ボトム）コーディング、丸めを用いる。','[{"id":"a","text":"電子メール：加工なし／業種：加工なし／体重：トップ・ボトムコーディング"},{"id":"b","text":"電子メール：加工なし／業種：加工なし／体重：トップ・ボトムコーディング＋丸め"},{"id":"c","text":"電子メール：加工なし／業種：項目削除／体重：項目削除"},{"id":"d","text":"電子メール：加工なし／業種：項目削除／体重：トップ・ボトムコーディング"},{"id":"e","text":"電子メール：加工なし／業種：項目削除／体重：トップ・ボトムコーディング＋丸め"},{"id":"f","text":"電子メール：項目削除／業種：加工なし／体重：トップ・ボトムコーディング"},{"id":"g","text":"電子メール：項目削除／業種：加工なし／体重：トップ・ボトムコーディング＋丸め"},{"id":"h","text":"電子メール：項目削除／業種：項目削除／体重：項目削除"},{"id":"i","text":"電子メール：項目削除／業種：項目削除／体重：トップ・ボトムコーディング"},{"id":"j","text":"電子メール：項目削除／業種：項目削除／体重：トップ・ボトムコーディング＋丸め"}]','"g"','電子メールアドレスは個人を直接識別し得るため削除する。分析対象に必要な勤務先業種は残し、体重は外れ値をまとめるトップ・ボトムコーディングと丸めを適用する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja');
